/* eslint-disable no-restricted-globals */
/**
 * Torah Chanting Aid — service worker for offline operation.
 * - Caches the React build assets, the bundled tessdata, and Google Fonts on first visit.
 * - Network-first for API calls (so live state updates stay fresh) with cache fallback.
 * - Cache-first for static assets so the app loads instantly when offline.
 */

const CACHE_VERSION = "torah-aid-v2";
const STATIC_CACHE = `${CACHE_VERSION}-static`;
const RUNTIME_CACHE = `${CACHE_VERSION}-runtime`;

// Pre-cache the most critical files on install. The other JS/CSS chunks
// generated by CRA will be cached on first fetch via the runtime cache.
const PRECACHE_URLS = [
  "/",
  "/index.html",
  "/fonts/fonts.css",
  "/fonts/NotoSerifHebrew-400.ttf",
  "/fonts/NotoSerifHebrew-700.ttf",
  "/fonts/CormorantGaramond-400.ttf",
  "/fonts/CormorantGaramond-600.ttf",
  "/fonts/Inter-400.ttf",
  "/fonts/Inter-500.ttf",
  "/tessdata/heb.traineddata.gz",
  "/tessdata/heb.traineddata",
  "/tesseract/worker.min.js",
  "/tesseract/tesseract-core-simd-lstm.wasm",
  "/tesseract/tesseract-core-simd-lstm.wasm.js",
  "/tesseract/tesseract-core-lstm.wasm",
  "/tesseract/tesseract-core-lstm.wasm.js",
  // MediaPipe Tasks Vision — hand landmarker model + WASM (offline)
  "/mediapipe/hand_landmarker.task",
  "/mediapipe/wasm/vision_wasm_internal.js",
  "/mediapipe/wasm/vision_wasm_internal.wasm",
  "/mediapipe/wasm/vision_wasm_nosimd_internal.js",
  "/mediapipe/wasm/vision_wasm_nosimd_internal.wasm",
];

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(STATIC_CACHE).then((cache) =>
      Promise.all(
        PRECACHE_URLS.map((url) =>
          cache.add(url).catch((e) => console.warn("[sw] precache miss", url, e))
        )
      )
    ).then(() => self.skipWaiting())
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys().then((keys) =>
      Promise.all(
        keys
          .filter((k) => !k.startsWith(CACHE_VERSION))
          .map((k) => caches.delete(k))
      )
    ).then(() => self.clients.claim())
  );
});

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") return;

  const url = new URL(request.url);

  // API requests: network-first, cache fallback
  if (url.pathname.startsWith("/api/")) {
    event.respondWith(
      fetch(request)
        .then((res) => {
          const copy = res.clone();
          caches.open(RUNTIME_CACHE).then((c) => c.put(request, copy));
          return res;
        })
        .catch(() => caches.match(request))
    );
    return;
  }

  // Static assets, fonts, tessdata, and same-origin app shell: cache-first.
  event.respondWith(
    caches.match(request).then((cached) => {
      if (cached) return cached;
      return fetch(request)
        .then((res) => {
          // Only cache successful, basic/CORS responses
          if (!res || res.status !== 200) return res;
          const copy = res.clone();
          const cacheName =
            url.origin === self.location.origin ? STATIC_CACHE : RUNTIME_CACHE;
          caches.open(cacheName).then((c) => c.put(request, copy));
          return res;
        })
        .catch(() => cached);
    })
  );
});
